package com.logiplatform.model;

import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="document_templates",uniqueConstraints=@UniqueConstraint(name="uk_template_code",columnNames={"tenant_id","template_code"}))
public class DocumentTemplate { @Id @GeneratedValue private UUID id; @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(name="template_code",nullable=false) private String templateCode; @Column(name="name",nullable=false) private String name; @Column(name="version",nullable=false) private String version; @Column(name="required_fields",columnDefinition="text") private String requiredFields; @Column(name="active",nullable=false) private boolean active=true; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); protected DocumentTemplate(){} public DocumentTemplate(UUID t,String c,String n,String v,String f){tenantId=t;templateCode=c;name=n;version=v;requiredFields=f;} public UUID getId(){return id;} public String getTemplateCode(){return templateCode;} public String getName(){return name;} public String getVersion(){return version;} public String getRequiredFields(){return requiredFields;} public boolean isActive(){return active;}}
